import Quickshell
import Quickshell.Io
import QtQuick
import qs.services

ShellRoot {
    id: root

    property bool expanded: false

    NextMeetingWindow {
        expanded: root.expanded
        onToggleRequested: root.expanded = !root.expanded
        onCloseRequested: root.expanded = false
    }

    IpcHandler {
        target: "next-meeting"

        function toggle(): void {
            root.expanded = !root.expanded;
        }
        function open(): void {
            root.expanded = true;
        }
        function close(): void {
            root.expanded = false;
        }
        function setUrl(url: string): void {
            Calendar.setUrl(url);
        }
        function refresh(): void {
            Calendar.refresh();
        }
        function join(): void {
            const event = Calendar.current ?? Calendar.next;
            if (event)
                Calendar.openUrl(event.joinUrl);
        }
        function status(): string {
            return Calendar.summary();
        }
    }
}

